-- Current official NCA ECC 2:2024 reconciliation (A-01), after A-04.
-- Official source: https://cdn.nca.gov.sa/api/files/public/upload/29a9e86a-595f-4af9-8db5-88715a458a14_ECC-2-2024---NCA.pdf
-- Source SHA-256: 66165b9ec3347efced2270540e0fd00a4246107a7b3aba6a5482c7db24671230
-- 108 base controls + 92 sub-controls. Retire two obsolete code identities
-- in an inactive archival framework; do not delete controls or audit history.
-- No assessment, mapping, evidence, scoring, or operational state is changed.
begin;
set local lock_timeout = '10s';
select set_config('private.catalog_maintenance', 'on', true);
select set_config(
  'private.catalog_maintenance_reason',
  '20260922184051 ECC current official NCA source reconciliation (A-01)',
  true
);

create temporary table ecc_current_catalog (
  control_code text primary key,
  official_text_ar text not null,
  source_page text not null,
  domain_ar text not null,
  hierarchy_level text not null,
  parent_code text,
  refresh_description boolean not null
) on commit drop;

insert into ecc_current_catalog
  (control_code, official_text_ar, source_page, domain_ar,
   hierarchy_level, parent_code, refresh_description)
values
  ('1-1-1', 'يجب تحديد وتوثيق واعتماد إستراتيجية الأمن السيبراني للجهة ودعمها من قبل رئيس الجهة أو من ينيبه (ويشار له في هذه الضوابط باسم "صاحب الصلاحية")، وأن تتماشى الأهداف الإستراتيجية للأمن السيبراني للجهة مع المتطلبات التشريعية والتنظيمية ذات العلاقة.', '15', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-1-2', 'يجب العمل على تنفيذ خطة عمل لتطبيق إستراتيجية الأمن السيبراني من قبل الجهة.', '15', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-1-3', 'يجب مراجعة إستراتيجية الأمن السيبراني على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية ذات العلاقة).', '15', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-2-1', 'يجب إنشاء إدارة معنية بالأمن السيبراني في الجهة (مستقلة عن إدارة تقنية المعلومات والاتصالات (ICT/IT)) (وفقاً للأمر السامي الكريم رقم 37140 وتاريخ 14/8/1438هـ). ويفضل ارتباطها مباشرة برئيس الجهة أو من ينيبه، مع الأخذ بالاعتبار عدم تعارض المصالح.', '15', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-2-2', 'يجب شغل جميع وظائف الأمن السيبراني من قبل مواطنين متفرغين وذوي كفاءة في مجال الأمن السيبراني.', '15', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-2-3', 'يجب إنشاء لجنة إشرافية للأمن السيبراني بتوجيه من صاحب الصلاحية للجهة لضمان التزام ودعم ومتابعة تطبيق برامج وتشريعات الأمن السيبراني، ويتم تحديد وتوثيق واعتماد أعضاء اللجنة ومسؤولياتها وإطار حوكمة أعمالها على أن يكون رئيس الإدارة المعنية بالأمن السيبراني أحد أعضائها. ويفضل ارتباطها مباشرة برئيس الجهة أو من ينيبه، مع الأخذ بالاعتبار عدم تعارض المصالح.', '15', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-3-1', 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة تحديد سياسات وإجراءات الأمن السيبراني وما تشمله من ضوابط ومتطلبات الأمن السيبراني، وتوثيقها واعتمادها من قبل صاحب الصلاحية في الجهة. كما يجب نشرها إلى ذوي العلاقة من العاملين في الجهة والأطراف المعنية بها.', '15', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-3-2', 'يجب على الإدارة المعنية بالأمن السيبراني ضمان تطبيق سياسات وإجراءات الأمن السيبراني في الجهة وما تشمله من ضوابط ومتطلبات.', '15', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-3-3', 'يجب أن تكون سياسات وإجراءات الأمن السيبراني مدعومة بمعايير تقنية أمنية (على سبيل المثال: المعايير التقنية الأمنية لجدار الحماية وقواعد البيانات، وأنظمة التشغيل، إلخ).', '15', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-3-4', 'يجب مراجعة سياسات وإجراءات ومعايير الأمن السيبراني وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية والمعايير ذات العلاقة)، كما يجب توثيق التغييرات واعتمادها.', '15', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-4-1', 'يجب على صاحب الصلاحية تحديد وتوثيق واعتماد الهيكل التنظيمي للحوكمة والأدوار والمسؤوليات الخاصة بالأمن السيبراني للجهة، وتكليف الأشخاص المعنيين بها، كما يجب تقديم الدعم اللازم لإنفاذ ذلك، مع الأخذ بالاعتبار عدم تعارض المصالح.', '16', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-4-2', 'يجب مراجعة أدوار ومسؤوليات الأمن السيبراني في الجهة وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية ذات العلاقة).', '16', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-5-1', 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة تحديد وتوثيق واعتماد منهجية وإجراءات إدارة مخاطر الأمن السيبراني في الجهة. وذلك وفقاً لاعتبارات السرية وتوافر وسلامة الأصول المعلوماتية والتقنية.', '16', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-5-2', 'يجب على الإدارة المعنية بالأمن السيبراني تطبيق منهجية وإجراءات إدارة مخاطر الأمن السيبراني في الجهة.', '16', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-5-3', 'يجب تنفيذ إجراءات تقييم مخاطر الأمن السيبراني بحد أدنى في الحالات التالية:', '16', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-5-3-1', 'في مرحلة مبكرة من المشاريع التقنية.', '16', 'حوكمة الأمن السيبراني', 'sub_control', '1-5-3', false),
  ('1-5-3-2', 'قبل إجراء تغيير جوهري في البنية التقنية.', '16', 'حوكمة الأمن السيبراني', 'sub_control', '1-5-3', false),
  ('1-5-3-3', 'عند التخطيط للحصول على خدمات طرف خارجي.', '16', 'حوكمة الأمن السيبراني', 'sub_control', '1-5-3', false),
  ('1-5-3-4', 'عند التخطيط وقبل إطلاق منتجات وخدمات تقنية جديدة.', '16', 'حوكمة الأمن السيبراني', 'sub_control', '1-5-3', false),
  ('1-5-4', 'يجب مراجعة منهجية وإجراءات إدارة مخاطر الأمن السيبراني وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية والمعايير ذات العلاقة)، كما يجب توثيق التغييرات واعتمادها.', '16', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-6-1', 'يجب تضمين متطلبات الأمن السيبراني في منهجية وإجراءات إدارة المشاريع وفي إدارة التغيير على الأصول المعلوماتية والتقنية في الجهة لضمان تحديد مخاطر الأمن السيبراني ومعالجتها كجزء من دورة حياة المشروع التقني، وأن تكون متطلبات الأمن السيبراني جزء أساسي من متطلبات المشاريع التقنية.', '16', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-6-2', 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة المشاريع والتغييرات على الأصول المعلوماتية والتقنية للجهة بحد أدنى ما يلي:', '16', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-6-2-1', 'تقييم الثغرات ومعالجتها.', '16', 'حوكمة الأمن السيبراني', 'sub_control', '1-6-2', false),
  ('1-6-2-2', 'إجراء مراجعة للإعدادات والتحصين (Secure Configuration and Hardening) وحزم التحديثات قبل إطلاق وتدشين المشاريع والتغييرات.', '16', 'حوكمة الأمن السيبراني', 'sub_control', '1-6-2', false),
  ('1-6-3', 'يجب أن تغطي متطلبات الأمن السيبراني لمشاريع تطوير التطبيقات والبرمجيات الخاصة للجهة بحد أدنى ما يلي:', '16', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-6-3-1', 'استخدام معايير التطوير الآمن للتطبيقات (Secure Coding Standards).', '16', 'حوكمة الأمن السيبراني', 'sub_control', '1-6-3', false),
  ('1-6-3-2', 'استخدام مصادر مرخصة وموثوقة لأدوات تطوير التطبيقات والمكتبات الخاصة بها (Libraries).', '16', 'حوكمة الأمن السيبراني', 'sub_control', '1-6-3', false),
  ('1-6-3-3', 'إجراء اختبار للتحقق من مدى استيفاء التطبيقات للمتطلبات الأمنية السيبرانية للجهة.', '16', 'حوكمة الأمن السيبراني', 'sub_control', '1-6-3', false),
  ('1-6-3-4', 'أمن التكامل (Integration) بين التطبيقات.', '16', 'حوكمة الأمن السيبراني', 'sub_control', '1-6-3', false),
  ('1-6-3-5', 'إجراء مراجعة للإعدادات والتحصين (Secure Configuration and Hardening) وحزم التحديثات قبل إطلاق وتدشين التطبيقات.', '16', 'حوكمة الأمن السيبراني', 'sub_control', '1-6-3', false),
  ('1-6-4', 'يجب مراجعة متطلبات الأمن السيبراني في إدارة المشاريع في الجهة دورياً.', '16', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-7-1', 'في حال وجود اتفاقيات أو التزامات دولية معتمدة محلياً تتضمن متطلبات خاصة بالأمن السيبراني، فيجب على الجهة حصر تلك المتطلبات والالتزام بها.', '17', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-8-1', 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة مراجعة تطبيق ضوابط الأمن السيبراني دورياً.', '17', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-8-2', 'يجب مراجعة وتدقيق تطبيق ضوابط الأمن السيبراني في الجهة، من قبل أطراف مستقلة عن الإدارة المعنية بالأمن السيبراني (مثل الإدارة المعنية بالمراجعة في الجهة). على أن تتم المراجعة والتدقيق بشكل مستقل يراعى فيه مبدأ عدم تعارض المصالح، وذلك وفقاً للمعايير العامة المقبولة للمراجعة والتدقيق والمتطلبات التشريعية والتنظيمية ذات العلاقة.', '17', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-8-3', 'يجب توثيق نتائج مراجعة وتدقيق الأمن السيبراني، وعرضها على اللجنة الإشرافية للأمن السيبراني وصاحب الصلاحية. كما يجب أن تشتمل النتائج على نطاق المراجعة والتدقيق، والملاحظات المكتشفة، والتوصيات والإجراءات التصحيحية، وخطة معالجة الملاحظات.', '17', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-9-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني المتعلقة بالعاملين قبل توظيفهم وأثناء عملهم وعند انتهاء/إنهاء عملهم في الجهة.', '17', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-9-2', 'يجب تطبيق متطلبات الأمن السيبراني المتعلقة بالعاملين في الجهة.', '17', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-9-3', 'يجب أن تغطي متطلبات الأمن السيبراني قبل بدء علاقة العاملين المهنية بالجهة بحد أدنى ما يلي:', '17', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-9-3-1', 'تضمين مسؤوليات الأمن السيبراني وبنود المحافظة على سرية المعلومات (Non-Disclosure Clauses) في عقود العاملين في الجهة (لتشمل خلال وبعد انتهاء/إنهاء العلاقة الوظيفية مع الجهة).', '17', 'حوكمة الأمن السيبراني', 'sub_control', '1-9-3', false),
  ('1-9-3-2', 'إجراء المسح الأمني (Screening or Vetting) للعاملين في وظائف الأمن السيبراني والوظائف التقنية ذات الصلاحيات الهامة والحساسة.', '17', 'حوكمة الأمن السيبراني', 'sub_control', '1-9-3', false),
  ('1-9-4', 'يجب أن تغطي متطلبات الأمن السيبراني خلال علاقة العاملين المهنية بالجهة بحد أدنى ما يلي:', '17', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-9-4-1', 'التوعية بالأمن السيبراني (عند بداية المهنة الوظيفية وخلالها).', '17', 'حوكمة الأمن السيبراني', 'sub_control', '1-9-4', false),
  ('1-9-4-2', 'تطبيق متطلبات الأمن السيبراني والالتزام بها وفقاً لسياسات وإجراءات وعمليات الأمن السيبراني للجهة.', '17', 'حوكمة الأمن السيبراني', 'sub_control', '1-9-4', false),
  ('1-9-5', 'يجب مراجعة وإلغاء الصلاحيات للعاملين مباشرة بعد انتهاء/إنهاء العلاقة الوظيفية مع الجهة.', '17', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-9-6', 'يجب مراجعة متطلبات الأمن السيبراني المتعلقة بالعاملين في الجهة دورياً.', '17', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-10-1', 'يجب تطوير واعتماد برنامج للتوعية بالأمن السيبراني في الجهة من خلال قنوات متعددة دورياً، وذلك لتعزيز الوعي بالأمن السيبراني وتهديداته ومخاطره، وبناء ثقافة إيجابية للأمن السيبراني.', '17', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-10-2', 'يجب تطبيق البرنامج المعتمد للتوعية بالأمن السيبراني في الجهة.', '17', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-10-3', 'يجب أن يغطي برنامج التوعية بالأمن السيبراني كيفية حماية الجهة من أهم المخاطر والتهديدات السيبرانية وما يستجد منها، بما في ذلك:', '17', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-10-3-1', 'التعامل الآمن مع خدمات البريد الإلكتروني خصوصاً مع رسائل التصيد الإلكتروني.', '17', 'حوكمة الأمن السيبراني', 'sub_control', '1-10-3', false),
  ('1-10-3-2', 'التعامل الآمن مع الأجهزة المحمولة ووسائط التخزين.', '18', 'حوكمة الأمن السيبراني', 'sub_control', '1-10-3', false),
  ('1-10-3-3', 'التعامل الآمن مع خدمات تصفح الإنترنت.', '18', 'حوكمة الأمن السيبراني', 'sub_control', '1-10-3', false),
  ('1-10-3-4', 'التعامل الآمن مع وسائل التواصل الاجتماعي.', '18', 'حوكمة الأمن السيبراني', 'sub_control', '1-10-3', false),
  ('1-10-4', 'يجب توفير المهارات المتخصصة والتدريب اللازم للعاملين في المجالات الوظيفية ذات العلاقة المباشرة بالأمن السيبراني في الجهة، وتصنيفها بما يتماشى مع مسؤولياتهم الوظيفية فيما يتعلق بالأمن السيبراني، بما في ذلك:', '18', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('1-10-4-1', 'موظفو الإدارة المعنية بالأمن السيبراني.', '18', 'حوكمة الأمن السيبراني', 'sub_control', '1-10-4', false),
  ('1-10-4-2', 'الموظفون العاملون في تطوير البرامج والتطبيقات والموظفون المشغلون للأصول المعلوماتية والتقنية للجهة.', '18', 'حوكمة الأمن السيبراني', 'sub_control', '1-10-4', false),
  ('1-10-4-3', 'الوظائف الإشرافية والتنفيذية.', '18', 'حوكمة الأمن السيبراني', 'sub_control', '1-10-4', false),
  ('1-10-5', 'يجب مراجعة تطبيق برنامج التوعية بالأمن السيبراني في الجهة دورياً.', '18', 'حوكمة الأمن السيبراني', 'control', null, false),
  ('2-1-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية للجهة.', '19', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-1-2', 'يجب تطبيق متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية للجهة.', '19', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-1-3', 'يجب تحديد وتوثيق واعتماد ونشر سياسة الاستخدام المقبول للأصول المعلوماتية والتقنية للجهة.', '19', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-1-4', 'يجب تطبيق سياسة الاستخدام المقبول للأصول المعلوماتية والتقنية للجهة.', '19', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-1-5', 'يجب تصنيف الأصول المعلوماتية والتقنية للجهة وترميزها (Labeling) والتعامل معها وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', '19', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-1-6', 'يجب مراجعة متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية للجهة دورياً.', '19', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-2-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة هويات الدخول والصلاحيات في الجهة.', '19', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-2-2', 'يجب تطبيق متطلبات الأمن السيبراني لإدارة هويات الدخول والصلاحيات في الجهة.', '19', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-2-3', 'يجب أن تغطي متطلبات الأمن السيبراني المتعلقة بإدارة هويات الدخول والصلاحيات في الجهة بحد أدنى ما يلي:', '19', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-2-3-1', 'التحقق من الهوية أحادي العنصر (Single-factor authentication) بناءً على إدارة تسجيل المستخدم، وإدارة كلمة المرور.', '19', 'تعزيز الأمن السيبراني', 'sub_control', '2-2-3', false),
  ('2-2-3-2', 'التحقق من الهوية متعدد العناصر (Multi-Factor Authentication) وتحديد عناصر التحقق المناسبة وعددها وكذلك تقنيات التحقق المناسبة بناءً على نتائج تقييم الأثر المحتمل لفشل عملية التحقق وتخطيها، وذلك لعمليات الدخول عن بعد والحسابات ذات الصلاحيات الهامة والحساسة.', '19', 'تعزيز الأمن السيبراني', 'sub_control', '2-2-3', true),
  ('2-2-3-3', 'إدارة تصاريح وصلاحيات المستخدمين بناءً على مبادئ التحكم بالدخول والصلاحيات (Authorization) (مبدأ الحاجة إلى المعرفة والاستخدام "Need-to-know and Need-to-use"، ومبدأ الحد الأدنى من الصلاحيات والامتيازات "Least Privilege"، ومبدأ فصل المهام "Segregation of Duties").', '19', 'تعزيز الأمن السيبراني', 'sub_control', '2-2-3', false),
  ('2-2-3-4', 'إدارة الصلاحيات الهامة والحساسة (Privileged Access Management).', '19', 'تعزيز الأمن السيبراني', 'sub_control', '2-2-3', false),
  ('2-2-3-5', 'المراجعة الدورية لهويات الدخول والصلاحيات.', '19', 'تعزيز الأمن السيبراني', 'sub_control', '2-2-3', false),
  ('2-2-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لإدارة هويات الدخول والصلاحيات في الجهة دورياً.', '19', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-3-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة.', '19', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-3-2', 'يجب تطبيق متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة.', '19', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-3-3', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة بحد أدنى ما يلي:', '19', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-3-3-1', 'الحماية من الفيروسات والبرامج والأنشطة المشبوهة والبرمجيات الضارة (Malware) على أجهزة المستخدمين والخوادم باستخدام تقنيات وآليات الحماية الحديثة والمتقدمة، وإدارتها بشكل آمن.', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-3-3', false),
  ('2-3-3-2', 'التقييد الحازم لاستخدام أجهزة وسائط التخزين الخارجية والأمن المتعلق بها.', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-3-3', true),
  ('2-3-3-3', 'إدارة حزم التحديثات والإصلاحات للأنظمة والتطبيقات والأجهزة (Patch Management).', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-3-3', false),
  ('2-3-3-4', 'مزامنة التوقيت (Clock Synchronization) مركزياً ومن مصدر دقيق وموثوق، ومن هذه المصادر ما توفره الهيئة السعودية للمواصفات والمقاييس والجودة.', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-3-3', false),
  ('2-3-4', 'يجب مراجعة متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة دورياً.', '20', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-4-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية البريد الإلكتروني للجهة.', '20', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-4-2', 'يجب تطبيق متطلبات الأمن السيبراني لحماية البريد الإلكتروني للجهة.', '20', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-4-3', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية البريد الإلكتروني للجهة بحد أدنى ما يلي:', '20', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-4-3-1', 'تحليل وتصفية (Filtering) رسائل البريد الإلكتروني (وخصوصاً رسائل التصيد الإلكتروني "Phishing Emails" والرسائل الإقتحامية "Spam Emails") باستخدام تقنيات وآليات الحماية الحديثة والمتقدمة للبريد الإلكتروني.', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-4-3', false),
  ('2-4-3-2', 'التحقق من الهوية متعدد العناصر (Multi-Factor Authentication) وتحديد عناصر التحقق المناسبة وعددها وكذلك تقنيات التحقق المناسبة بناء على نتائج تقييم الأثر المحتمل لفشل عملية التحقق وتخطيها، وذلك للدخول عن بعد والدخول عن طريق صفحة موقع البريد الإلكتروني (Webmail).', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-4-3', true),
  ('2-4-3-3', 'النسخ الاحتياطي والأرشفة للبريد الإلكتروني.', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-4-3', false),
  ('2-4-3-4', 'الحماية من التهديدات المتقدمة المستمرة (APT Protection)، التي تستخدم عادة الفيروسات والبرمجيات الضارة غير المعروفة مسبقاً (Zero-Day Malware)، وإدارتها بشكل آمن.', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-4-3', false),
  ('2-4-3-5', 'توثيق مجال البريد الإلكتروني للجهة باستخدام إطار سياسة المرسل (Sender Policy Framework "SPF") والبريد المعرّف بمفاتيح النطاق (Domain Keys Identified Mail "DKIM") وسياسة مصادقة الرسائل والإبلاغ عنها (Domain Message Authentication Reporting and Conformance "DMARC").', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-4-3', true),
  ('2-4-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني الخاصة بحماية البريد الإلكتروني للجهة دورياً.', '20', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-5-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة.', '20', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-5-2', 'يجب تطبيق متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة.', '20', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-5-3', 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة بحد أدنى ما يلي:', '20', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-5-3-1', 'العزل والتقسيم المادي أو المنطقي لأجزاء الشبكات بشكل آمن، واللازم للسيطرة على مخاطر الأمن السيبراني ذات العلاقة، باستخدام جدار الحماية (Firewall) ومبدأ الدفاع الأمني متعدد المراحل (Defense-in-Depth).', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-5-3', false),
  ('2-5-3-2', 'عزل شبكة بيئة الإنتاج عن شبكات بيئات التطوير والاختبار.', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-5-3', false),
  ('2-5-3-3', 'أمن التصفح والاتصال بالإنترنت، ويشمل ذلك التقييد الحازم للمواقع الإلكترونية المشبوهة، ومواقع مشاركة وتخزين الملفات، ومواقع الدخول عن بعد.', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-5-3', false),
  ('2-5-3-4', 'أمن الشبكات اللاسلكية وحمايتها باستخدام وسائل آمنة للتحقق من الهوية والتشفير، وعدم ربط الشبكات اللاسلكية بشبكة الجهة الداخلية إلا بناءً على دراسة متكاملة للمخاطر المترتبة على ذلك والتعامل معها بما يضمن حماية الأصول التقنية للجهة.', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-5-3', false),
  ('2-5-3-5', 'قيود وإدارة منافذ وبروتوكولات وخدمات الشبكة.', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-5-3', false),
  ('2-5-3-6', 'أنظمة الحماية المتقدمة لاكتشاف ومنع الاختراقات (Intrusion Prevention Systems).', '20', 'تعزيز الأمن السيبراني', 'sub_control', '2-5-3', false),
  ('2-5-3-7', 'أمن نظام أسماء النطاقات (DNS).', '21', 'تعزيز الأمن السيبراني', 'sub_control', '2-5-3', false),
  ('2-5-3-8', 'حماية قناة تصفح الإنترنت من التهديدات المتقدمة المستمرة (APT Protection)، التي تستخدم عادة الفيروسات والبرمجيات الضارة غير المعروفة مسبقاً (Zero-Day Malware)، وإدارتها بشكل آمن.', '21', 'تعزيز الأمن السيبراني', 'sub_control', '2-5-3', false),
  ('2-5-3-9', 'الحماية من هجمات تعطيل الشبكات (Distributed Denial of Service Attack "DDoS") للحد من المخاطر السيبرانية الناتجة عن هجمات تعطيل الشبكات.', '21', 'تعزيز الأمن السيبراني', 'sub_control', '2-5-3', true),
  ('2-5-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة دورياً.', '21', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-6-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة والأجهزة الشخصية للعاملين (BYOD) عند ارتباطها بشبكة الجهة.', '21', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-6-2', 'يجب تطبيق متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة وأجهزة (BYOD) للجهة.', '21', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-6-3', 'يجب أن تغطي متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة وأجهزة (BYOD) للجهة بحد أدنى ما يلي:', '21', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-6-3-1', 'فصل وتشفير البيانات والمعلومات (الخاصة بالجهة) المخزنة على الأجهزة المحمولة وأجهزة (BYOD).', '21', 'تعزيز الأمن السيبراني', 'sub_control', '2-6-3', false),
  ('2-6-3-2', 'الاستخدام المحدد والمقيد بناءً على ما تتطلبه مصلحة أعمال الجهة.', '21', 'تعزيز الأمن السيبراني', 'sub_control', '2-6-3', false),
  ('2-6-3-3', 'حذف البيانات والمعلومات (الخاصة بالجهة) المخزنة على الأجهزة المحمولة وأجهزة (BYOD) عند فقدان الأجهزة أو بعد انتهاء/إنهاء العلاقة الوظيفية مع الجهة.', '21', 'تعزيز الأمن السيبراني', 'sub_control', '2-6-3', false),
  ('2-6-3-4', 'التوعية الأمنية للمستخدمين.', '21', 'تعزيز الأمن السيبراني', 'sub_control', '2-6-3', false),
  ('2-6-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني الخاصة لأمن الأجهزة المحمولة وأجهزة (BYOD) للجهة دورياً.', '21', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-7-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية بيانات ومعلومات الجهة، والتعامل معها وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', '21', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-7-2', 'يجب تطبيق متطلبات الأمن السيبراني لحماية بيانات ومعلومات الجهة، حسب مستوى تصنيفها.', '21', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-7-3', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لحماية بيانات ومعلومات الجهة دورياً.', '21', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-8-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني للتشفير في الجهة.', '21', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-8-2', 'يجب تطبيق متطلبات الأمن السيبراني للتشفير في الجهة.', '21', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-8-3', 'يجب أن تغطي متطلبات الأمن السيبراني للتشفير بحد أدنى المتطلبات المذكورة في المعايير الوطنية للتشفير الصادرة من الهيئة، مع تطبيق مستوى التشفير المناسب، وذلك بحسب طبيعة ومستوى حساسية البيانات والأنظمة والشبكات وبناءً على تقييم المخاطر من قبل الجهة وحسب المتطلبات التشريعية والتنظيمية ذات العلاقة، وفقاً لما يلي:', '21', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-8-3-1', 'معايير أنظمة وحلول التشفير المعتمدة والقيود المطبقة عليها (تقنياً وتنظيمياً).', '21', 'تعزيز الأمن السيبراني', 'sub_control', '2-8-3', false),
  ('2-8-3-2', 'الإدارة الآمنة لمفاتيح التشفير خلال عمليات دورة حياتها.', '21', 'تعزيز الأمن السيبراني', 'sub_control', '2-8-3', false),
  ('2-8-3-3', 'تشفير البيانات أثناء النقل والتخزين والمعالجة بناءً على تصنيفها وحسب المتطلبات التشريعية والتنظيمية ذات العلاقة.', '22', 'تعزيز الأمن السيبراني', 'sub_control', '2-8-3', false),
  ('2-8-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني للتشفير في الجهة دورياً.', '22', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-9-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية للجهة.', '22', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-9-2', 'يجب تطبيق متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية للجهة.', '22', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-9-3', 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية بحد أدنى ما يلي:', '22', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-9-3-1', 'نطاق النسخ الاحتياطية وشموليتها للأصول المعلوماتية والتقنية الحساسة.', '22', 'تعزيز الأمن السيبراني', 'sub_control', '2-9-3', false),
  ('2-9-3-2', 'القدرة السريعة على استعادة البيانات والأنظمة بعد التعرض لحوادث الأمن السيبراني.', '22', 'تعزيز الأمن السيبراني', 'sub_control', '2-9-3', false),
  ('2-9-3-3', 'إجراء فحص دوري لمدى فعالية استعادة النسخ الاحتياطية.', '22', 'تعزيز الأمن السيبراني', 'sub_control', '2-9-3', false),
  ('2-9-4', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية للجهة.', '22', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-10-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة الثغرات التقنية للجهة.', '22', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-10-2', 'يجب تطبيق متطلبات الأمن السيبراني لإدارة الثغرات التقنية للجهة.', '22', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-10-3', 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة الثغرات بحد أدنى ما يلي:', '22', 'تعزيز الأمن السيبراني', 'control', null, false),
  ('2-10-3-1', 'فحص واكتشاف الثغرات دورياً.', '22', 'تعزيز الأمن السيبراني', 'sub_control', '2-10-3', false),
  ('2-10-3-2', 'تصنيف الثغرات حسب خطورتها.', '22', 'تعزيز الأمن السيبراني', 'sub_control', '2-10-3', false),
  ('2-10-3-3', 'معالجة الثغرات بناءً على تصنيفها والمخاطر السيبرانية المترتبة عليها.', '22', 'تعزيز الأمن السيبراني', 'sub_control', '2-10-3', false),
  ('2-10-3-4', 'إدارة حزم التحديثات والإصلاحات الأمنية لمعالجة الثغرات، على أن يتم التحقق من سلامة وفعالية تلك التحديثات والإصلاحات الأمنية على بيئة غير بيئة الإنتاج قبل تطبيقها.', '22', 'تعزيز الأمن السيبراني', 'sub_control', '2-10-3', false),
