  ('4-1-2-1', 'بنود المحافظة على سرية المعلومات (Non-Disclosure Clauses) والحذف الآمن من قبَل الطرف الخارجي لبيانات الجهة عند انتهاء الخدمة.', '26', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '4-1-2', false),
  ('4-1-2-2', 'إجراءات التواصل في حال حدوث حادثة أمن سيبراني.', '26', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '4-1-2', false),
  ('4-1-2-3', 'إلزام الطرف الخارجي بتطبيق متطلبات وسياسات الأمن السيبراني للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', '26', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '4-1-2', false),
  ('4-1-3', 'يجب أن تغطي متطلبات الأمن السيبراني مع الأطراف الخارجية التي تقدم خدمات الإسناد للأمن السيبراني أو لتقنية المعلومات، أو الخدمات المدارة بحد أدنى ما يلي:', '26', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', null, false),
  ('4-1-3-1', 'إجراء تقييم لمخاطر الأمن السيبراني، والتأكد من وجود ما يضمن السيطرة على تلك المخاطر، قبل توقيع العقود والاتفاقيات أو عند تغيير المتطلبات التشريعية والتنظيمية ذات العلاقة.', '26', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '4-1-3', false),
