  ('4-1-4', 'يجب مراجعة متطلبات الأمن السيبراني مع الأطراف الخارجية دورياً.', '26', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', null, false),
  ('4-2-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني الخاصة باستخدام خدمات الحوسبة السحابية والاستضافة.', '26', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', null, false),
  ('4-2-2', 'يجب تطبيق متطلبات الأمن السيبراني الخاصة بخدمات الحوسبة السحابية والاستضافة للجهة.', '26', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', null, false),
  ('4-2-3', 'بما يتوافق مع المتطلبات التشريعية والتنظيمية ذات العلاقة، وبالإضافة إلى ما ينطبق من الضوابط ضمن المكونات الرئيسية رقم (1) و(2) و(3) والمكون الفرعي رقم (4-1) الضرورية لحماية بيانات الجهة أو الخدمات المقدمة لها، يجب أن تغطي متطلبات الأمن السيبراني الخاصة باستخدام خدمات الحوسبة السحابية والاستضافة بحد أدنى ما يلي:', '26', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', null, false),
  ('4-2-3-1', 'حماية بيانات الجهة من قبل مقدمي خدمات الحوسبة السحابية والاستضافة بما يتوافق مع مستوى تصنيفها، وإعادتها للجهة (بصيغة قابلة للاستخدام) عند انتهاء الخدمة.', '26', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '4-2-3', true),
  ('4-2-3-2', 'فصل البيئة الخاصة بالجهة (وخصوصاً الخوادم الافتراضية) عن غيرها من البيئات التابعة لجهات أخرى في خدمات الحوسبة السحابية.', '26', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'sub_control', '4-2-3', false),
  ('4-2-4', 'يجب مراجعة متطلبات الأمن السيبراني الخاصة بخدمات الحوسبة السحابية والاستضافة دورياً.', '26', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'control', null, false);

do $reconcile$
declare
  ecc_id bigint;
  archive_id bigint;
  retiring_ids bigint[];
  fk record;
  reference_count bigint;
begin
  if current_user <> 'postgres' or session_user <> 'postgres' then
    raise exception 'ECC catalog reconciliation requires a postgres migration session';
  end if;
  if (select count(*) from ecc_current_catalog) <> 200
     or (select count(*) from ecc_current_catalog where hierarchy_level = 'control') <> 108
     or (select count(*) from ecc_current_catalog where hierarchy_level = 'sub_control') <> 92 then
    raise exception 'The official ECC source manifest must contain 108 base and 92 sub-controls';
  end if;
  if exists (
    select 1 from ecc_current_catalog child
    where child.parent_code is not null
      and not exists (
        select 1 from ecc_current_catalog parent
        where parent.control_code = child.parent_code
          and parent.hierarchy_level = 'control'
      )
  ) then
    raise exception 'Official ECC source manifest has an invalid parent';
  end if;
  if (select count(*) from public.frameworks where code = 'ECC') <> 1 then
    raise exception 'Expected exactly one active ECC framework';
  end if;
  select id into ecc_id from public.frameworks where code = 'ECC' and is_active;
  if ecc_id is null then
    raise exception 'ECC framework is not active';
  end if;
  if exists (
    select 1 from public.controls c
    where c.framework_id = ecc_id
      and c.control_code not in (select control_code from ecc_current_catalog)
      and c.control_code not in ('1-7-2', '2-7-4')
  ) then
    raise exception 'Unexpected active ECC code; manual investigation required';
  end if;
  if (select count(*) from public.controls where framework_id = ecc_id)
       not in (200, 202) then
    raise exception 'Unexpected pre-migration active ECC item count';
  end if;
  if (select count(*) from public.controls c
      join ecc_current_catalog src using (control_code)
      where c.framework_id = ecc_id) <> 200 then
    raise exception 'Current ECC source codes are missing or duplicated in QA';
  end if;
  if exists (
    select 1 from public.controls c
    join ecc_current_catalog src using (control_code)
    where c.framework_id = ecc_id
      and (
        c.hierarchy_level is distinct from src.hierarchy_level
        or c.domain_ar is distinct from src.domain_ar
        or (select p.control_code
            from public.controls p where p.id = c.parent_control_id)
           is distinct from src.parent_code
      )
  ) then
    raise exception 'ECC hierarchy/domain drift requires separate review';
  end if;

  -- Only the two obsolete row identities may move. All non-audit foreign-key
  -- references must be absent; historical grc_audit_events references remain.
  select array_agg(id) into retiring_ids
  from public.controls
  where framework_id = ecc_id
    and (control_code = '1-7-2'
      or (control_code = '2-7-3' and exists (
        select 1 from public.controls
        where framework_id = ecc_id and control_code = '2-7-4'
      )));
  if coalesce(array_length(retiring_ids, 1), 0) > 0 then
    for fk in
      select format('%I.%I', ns.nspname, rel.relname) as table_name,
             att.attname as column_name
      from pg_constraint con
      join pg_class rel on rel.oid = con.conrelid
      join pg_namespace ns on ns.oid = rel.relnamespace
      join pg_attribute att
        on att.attrelid = con.conrelid and att.attnum = con.conkey[1]
      where con.contype = 'f'
        and con.confrelid = 'public.controls'::regclass
        and cardinality(con.conkey) = 1
        and con.conrelid <> 'public.grc_audit_events'::regclass
    loop
      execute format(
        'select count(*) from %s where %I = any($1)',
        fk.table_name, fk.column_name
      ) into reference_count using retiring_ids;
      if reference_count <> 0 then
        raise exception 'Obsolete ECC IDs have % references in %.%',
          reference_count, fk.table_name, fk.column_name;
      end if;
    end loop;
    -- Keep operational columns on the historical row exactly as they are.
    -- In particular, a legacy free-text owner may exist in a Production-like
    -- baseline even when QA has no owner on the same obsolete code.
  end if;

  select id into archive_id from public.frameworks
  where code = 'ECC_RETIRED_2_2024';
  if archive_id is null then
    insert into public.frameworks
      (code, name_ar, name_en, version, description_ar, is_active, source_url)
    values (
      'ECC_RETIRED_2_2024',
      'أرشيف ضوابط الأمن السيبراني الأساسية المستبدلة',
      'Retired ECC 2:2024 catalog identities',
      '2-2024-retired',
      'أرشيف للمعرّفات التنظيمية السابقة 1-7-2 و2-7-3؛ غير نشط ولا يستخدم في التقييمات الجديدة.',
      false,
      'https://cdn.nca.gov.sa/api/files/public/upload/e4c81aa9-a609-4823-abab-347283e29731_ECC-2-2024-AR-19092024-.pdf'
    ) returning id into archive_id;
  elsif (select is_active from public.frameworks where id = archive_id) then
    raise exception 'Retired ECC archival framework must be inactive';
  end if;

  update public.controls
  set framework_id = archive_id
  where framework_id = ecc_id
    and control_code = '1-7-2';

  if exists (
    select 1 from public.controls
    where framework_id = ecc_id and control_code = '2-7-4'
  ) then
    update public.controls
    set framework_id = archive_id
    where framework_id = ecc_id and control_code = '2-7-3';

    update public.controls
    set control_code = '2-7-3',
        title_ar = regexp_replace(title_ar, '2-7-4$', '2-7-3')
    where framework_id = ecc_id and control_code = '2-7-4';
  end if;

  -- Refresh only source-of-truth content and six descriptions that still
  -- repeated superseded wording. All other descriptions and operational
  -- fields remain unchanged.
  update public.controls c
  set official_text_ar = src.official_text_ar,
      source_page = src.source_page,
      description_ar = case when src.refresh_description
        then src.official_text_ar else c.description_ar end
  from ecc_current_catalog src
  where c.framework_id = ecc_id
    and c.control_code = src.control_code
    and (
      c.official_text_ar is distinct from src.official_text_ar
      or c.source_page is distinct from src.source_page
      or (src.refresh_description
          and c.description_ar is distinct from src.official_text_ar)
    );

  update public.frameworks
  set source_url =
    'https://cdn.nca.gov.sa/api/files/public/upload/29a9e86a-595f-4af9-8db5-88715a458a14_ECC-2-2024---NCA.pdf'
  where id = ecc_id
    and source_url is distinct from
    'https://cdn.nca.gov.sa/api/files/public/upload/29a9e86a-595f-4af9-8db5-88715a458a14_ECC-2-2024---NCA.pdf';

  if (select count(*) from public.controls where framework_id = ecc_id) <> 200
     or (select count(*) from public.controls
         where framework_id = ecc_id and hierarchy_level = 'control') <> 108
     or (select count(*) from public.controls
         where framework_id = ecc_id and hierarchy_level = 'sub_control') <> 92 then
    raise exception 'Final active ECC catalog does not have 108 + 92 rows';
  end if;
  if exists (
    select 1 from ecc_current_catalog src
    left join public.controls c
      on c.framework_id = ecc_id and c.control_code = src.control_code
    left join public.controls parent
      on parent.id = c.parent_control_id
    where c.id is null
      or c.official_text_ar is distinct from src.official_text_ar
      or c.source_page is distinct from src.source_page
      or c.domain_ar is distinct from src.domain_ar
      or c.hierarchy_level is distinct from src.hierarchy_level
      or parent.control_code is distinct from src.parent_code
  ) then
    raise exception 'Final active ECC catalog differs from official source manifest';
  end if;
  if (select count(*) from public.controls
      where framework_id = archive_id
        and control_code in ('1-7-2', '2-7-3')) <> 2 then
    raise exception 'Both superseded ECC identities must be archived';
  end if;
end
$reconcile$;

commit;
